API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Ingress Router, "Ingress Router", "Envoy / NGINX", "Provides high-performance ingress routing, payload sanitization, and TLS termination.")
    Component(Security Filter, "Security Filter", "Lua / WASM", "Executes low-latency JWT validation, MFA verification, and scope-based access checks.")
    Component(Rate Limiter, "Rate Limiter", "Redis (Cluster)", "Powers token-bucket rate limiting and distributed token revocation checks.")
}

Rel(Ingress Router, Security Filter, "Forwards requests for validation and authentication")
Rel(Security Filter, Rate Limiter, "Checks rate limits and token revocation")
@enduml

FHIR Integration Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fhir_integration_engine, "FHIR Integration Engine") {
    Component(fhir_router, "FHIR Router", "Apache Camel", "Routes and maps incoming HL7 FHIR messages to internal domain models.")
    Component(fhir_resource_mapper, "FHIR Resource Mapper", "Node.js", "Transforms FHIR resources for persistence in the Core Datastore.")
}

SystemDb(core_datastore, "Core Datastore", "PostgreSQL with CQRS", "Persists clinical and domain data.")

Rel(fhir_router, fhir_resource_mapper, "Routes mapped payloads")
Rel(fhir_resource_mapper, core_datastore, "Persists clinical data using PostgreSQL with CQRS")

@enduml

Core Datastore.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(core_datastore, "Core Datastore") {
    Component(PrimaryWriteDatastore, "Primary Write Datastore", "PostgreSQL Master", "Handles persistent write traffic for EMRs, patient admissions, and billing.")
    Component(ReadReplicas, "Read Replicas", "PostgreSQL Read Replicas", "Handles read traffic utilizing CQRS pattern to ensure sub-second EMR retrieval.")
}

Rel(PrimaryWriteDatastore, ReadReplicas, "Synchronizes data changes for read isolation and performance.", "PostgreSQL replication")
@enduml
